import{_ as a,o,c as r,a2 as t}from"./chunks/framework.DTwTvi8b.js";const u=JSON.parse('{"title":"0026 本机的需求索引、使用记录和 req api","description":"","frontmatter":{"editLink":false},"headers":[],"relativePath":"reference/adr/0026-machine-records-and-api.md","filePath":"reference/adr/0026-machine-records-and-api.md","lastUpdated":null}'),i={name:"reference/adr/0026-machine-records-and-api.md"};function d(c,e,s,n,l,p){return o(),r("div",null,[...e[0]||(e[0]=[t('<div><h1 id="_0026-本机的需求索引、使用记录和-req-api" tabindex="-1">0026 本机的需求索引、使用记录和 req api <a class="header-anchor" href="#_0026-本机的需求索引、使用记录和-req-api" aria-label="Permalink to &quot;0026 本机的需求索引、使用记录和 req api&quot;">​</a></h1><ul><li>状态：已采纳（补充 <a href="./0010-generated-feature-overview">0010</a>：仓库内的总览仍现场生成；<a href="./0014-notifier-slot">0014</a>：通知槽不变）</li></ul><h2 id="背景" tabindex="-1">背景 <a class="header-anchor" href="#背景" aria-label="Permalink to &quot;背景&quot;">​</a></h2><p>1.9 要做两件依赖同一份数据的事：Paseo 插件在网页端列出本机所有项目的需求、做确认和停止这类管理操作；管理方要定期看到 req-kit 的使用情况（多少需求、多快、返工多少、花了多少）。在此之前，需求的状态分散在各仓库各工作区的功能目录里，<code>req list</code> 只看得到当前仓库；用时和用量只在每个需求的状态文件中，没有跨需求的汇总；<code>req list</code>、<code>req status</code> 只输出给人看的文字，程序要用只能解析文字或直接读状态文件，后者把状态文件的内部格式变成了对外约定。</p><h2 id="决定" tabindex="-1">决定 <a class="header-anchor" href="#决定" aria-label="Permalink to &quot;决定&quot;">​</a></h2><ul><li><strong>需求索引</strong>：引擎每次写状态文件时，确认本机配置目录下的 <code>index/&lt;key&gt;.json</code> 记着这个需求在哪里（目录、功能目录、对话所在目录、工作区），一个需求一个文件，几个流水线同时运行也不会互相覆盖。索引只记位置，阶段和进度仍然现场从功能目录读取，所以不会和实际情况不一致。</li><li><strong>使用记录</strong>：每次运行（后台进程从开始到结束）结束时向 <code>usage/runs.jsonl</code> 追加一行：步骤、用时、用量、质量门、结束时的状态。按运行而不是按需求记，追加即可，不用改写旧记录；需求层面的数字（交付周期、评审轮数、等待时长）在统计时从同一需求的各次运行算出。</li><li><strong>只在本机，不自动上报</strong>：两样都不提交进仓库，也不发往任何地方；不记需求内容和代码。汇总给管理方时由人导出（<code>req stats --export</code>）再合并（<code>--merge</code>）；之后定下汇总通道时，用 1.9 的集成模块订阅&quot;运行结束&quot;，数据格式不变。</li><li><strong><code>req stats</code></strong>：Markdown 汇总、JSON、每个需求一行的 CSV，<code>--report</code> 生成汇报用的两份文件。</li><li><strong><code>req api</code></strong>：给程序的稳定接口，一行 JSON，带 <code>schema</code>。读操作（list、status、file、stats、index）不改变任何东西；管理操作 <code>req api run &lt;approve|stop|resume|verify&gt;</code> 就是在相应目录执行 <code>req &lt;命令&gt;</code>，引擎仍是唯一修改状态的一方。<code>file</code> 只能读功能目录中的文档白名单。</li><li><strong>评估和测试不进记录</strong>：<code>REQ_KIT_NO_RECORD=1</code> 关闭记录，评估运行设置它；测试把本机配置目录指向临时目录。</li></ul><h2 id="影响" tabindex="-1">影响 <a class="header-anchor" href="#影响" aria-label="Permalink to &quot;影响&quot;">​</a></h2><ul><li>插件和脚本只依赖 <code>contracts/cli-json.md</code>，状态文件的内部格式可以继续演进。</li><li>1.9 之前运行过的需求不在索引里，需要 <code>req index --rebuild</code> 补登；删掉的目录在索引里显示为&quot;已移除&quot;，<code>--prune</code> 清理。</li><li>记录是尽力而为的：写失败不影响流水线，被强制结束（kill -9、断电）的运行没有记录，统计会少算这次运行。</li><li>主机名写进每条记录，用于合并多台机器的数据时区分来源。</li></ul></div><p class="source-note">本页由仓库中的 <a href="https://github.com/yiyisf/paseo-req-kit/blob/main/docs/adr/0026-machine-records-and-api.md">docs/adr/0026-machine-records-and-api.md</a> 生成。<a href="https://github.com/yiyisf/paseo-req-kit/edit/main/docs/adr/0026-machine-records-and-api.md">在 GitHub 上编辑</a></p>',2)])])}const m=a(i,[["render",d]]);export{u as __pageData,m as default};
